{quest=4625,objective="Parlez à Gathwën",text="Vous pourriez retrouver Gathwën près de la tombe d'Uldor, au fond du temple, pour faire le point après la fermeture de la prison.",step="J'ai placé les larmes des deux Lunes sur leurs piédestaux, enfermant Uldor dans sa tombe. Je devrais dire au revoir à Gathwën avant de partir.",binding="iq_exact_phase",answerComplete=true,source="Client et Immersive Quests FR : géographie vérifiée"},
{quest=4625,objective="Parlez à Gathwën",text="dans la crypte du grand hall.",step="Le cristal d'eau qui se trouvait autrefois dans le temple – la « pierre du deuil » – est la clef pour renvoyer Uldor dans sa tombe. Rurélion pense que la seule solution consiste à s'enfermer à jamais dans la tombe, mais Gathwën n'est pas d'accord. Il faut que je lui demande ce qu'elle propose à la place.",binding="iq_exact_phase",answerComplete=false,source="Client et Immersive Quests FR : géographie vérifiée"},
{quest=4625,objective="Parlez à Rurélion",text="Vous pourriez retrouver Rurélion dans la crypte du grand hall.",step="Rurélion a forcé Uldor à quitter son corps et rejoindre une tombe à proximité, mais cette solution n'est que temporaire. Il faut que je voie avec Rurélion comment faire pour qu'il y reste à jamais.",binding="iq_exact_phase",answerComplete=true,source="Client et Immersive Quests FR : géographie vérifiée"},
{quest=4625,objective="Parlez à Rurélion",text="Vous pourriez retrouver Rurélion dans le grand hall du temple, à l’écart de la tombe.",step="Uldor et Gathwën sont maintenant enfermés dans la Tombe des lunes descendantes. Je dois parler à Rurélion avant mon départ.",binding="iq_exact_phase",answerComplete=true,source="Client et Immersive Quests FR : géographie vérifiée"},
{quest=4625,objective="Parlez au squelette",text="Dans la cour du temple, vous pourriez prêter attention au squelette qui cherche à vous parler avant de poursuivre vers les protections magiques.",binding="iq_goal_rule",answerComplete=true,source="Client et Immersive Quests FR : géographie vérifiée"},
{quest=4625,objective="Pénétrez dans les catacombes du temple",text="Une fois les protections désactivées dans la cour, vous pourriez reprendre l'accès qui descend sous le temple, vers les catacombes.",binding="iq_goal_rule",answerComplete=true,source="Client et Immersive Quests FR : géographie vérifiée"},
{quest=4625,objective="Trouvez Rurélion",text="Vous pourriez poursuivre dans les ruines intérieures du temple, au-delà des catacombes, vers les manifestations du rituel d'Uldor.",binding="iq_goal_rule",answerComplete=true,source="Client et Immersive Quests FR : géographie vérifiée"},
